INSERT INTO restaurante_categorias (restaurante_id, categoria_id)
SELECT r.id, c.id
FROM pares p
JOIN restaurantes r ON r.slug = p.restaurante_slug
JOIN categorias c ON c.slug = p.categoria_slug
ON CONFLICT DO NOTHING;

CREATE OR REPLACE VIEW foodmood_restaurants_app AS
SELECT
  r.slug AS id,
  r.nombre AS name,
  COALESCE(r.descripcion, '') AS description,
  COALESCE(array_remove(array_agg(DISTINCT c.nombre), NULL), ARRAY[]::varchar[]) AS categories,
  COALESCE(array_remove(ARRAY[r.tipo_cocina, r.corregimiento], NULL), ARRAY[]::varchar[]) AS tags,
  COALESCE(NULLIF(r.rango_precio, ''), '$$') AS price_level,
  ARRAY['Casual']::text[] AS ambience,
  COALESCE(r.instagram, '') AS instagram,
  r.direccion AS address,
  COALESCE(r.corregimiento, r.distrito, r.provincia) AS zone,
  COALESCE(r.rating, 0)::float AS rating,
  COALESCE(r.horario, 'Horario por confirmar') AS opening_hours,
  r.sitio_web AS website,
  r.imagen_url AS image_url,
  r.latitud::float AS latitude,
  r.longitud::float AS longitude,
  r.activo AS active
FROM restaurantes r
LEFT JOIN restaurante_categorias rc ON rc.restaurante_id = r.id
LEFT JOIN categorias c ON c.id = rc.categoria_id
WHERE r.activo = TRUE
GROUP BY r.id;
